224	async function safeListRepositoryInsights(
225	  manager: KnowledgeStoreManager,
226	  repoName: string
227	): Promise<Insight[]> {
228	  try {
229	    return await manager.listInsights({ scope: 'repository', repository_name: repoName });
230	  } catch (err) {
231	    const message = err instanceof Error ? err.message : String(err);
232	    if (
233	      message.startsWith('Invalid repository name:') ||
234	      message.startsWith("'global' is a reserved name")
235	    ) {
236	      return [];
237	    }
238	    throw err;
239	  }
240	}
