400	/**
401	 * Seeds a knowledge store JSON file at the given path.
402	 * The `insights` array is written as-is; `next_id` is set to max(id)+1.
403	 */
404	async function seedKnowledgeStore(
405	  filePath: string,
406	  insights: Array<Record<string, unknown>>
407	): Promise<void> {
408	  const dir = filePath.substring(0, filePath.lastIndexOf('/'));
409	  await mkdir(dir, { recursive: true });
410	  const maxId = insights.reduce((m, ins) => Math.max(m, (ins['id'] as number) ?? 0), 0);
411	  const store = {
412	    version: '1.0.0',
413	    last_updated: new Date().toISOString(),
414	    next_id: maxId + 1,
415	    insights,
416	  };
417	  await writeFile(filePath, JSON.stringify(store, null, 2), 'utf-8');
418	}
